import {test,describe,beforeAll,afterAll,aroundAll} from 'vitest'
import {appendFileSync} from 'node:fs'
const trace=(...row)=>appendFileSync('authored.jsonl',JSON.stringify(row)+'\n')
let releaseRoot
const actualSettled=new Promise(resolve=>{releaseRoot=resolve})
let wrapperPending=true
afterAll(async()=>{trace('root-afterAll-wait');await actualSettled;trace('root-afterAll-settled')},5000)
describe('affected',()=>{
 aroundAll(async run=>{
  trace('wrapper-entry')
  try {
   await new Promise(resolve=>setTimeout(resolve,250))
   trace('wrapper-late-run')
   try {await run();trace('wrapper-late-run-complete')}
   catch(error){trace('wrapper-late-run-rejected',{name:error.name,message:error.message,own:Object.fromEntries(Object.getOwnPropertyNames(error).map(key=>[key,error[key]]))})}
  } finally {wrapperPending=false;trace('wrapper-finally');releaseRoot()}
 },100)
 describe('blocked empty',()=>{beforeAll(()=>trace('blocked-empty-beforeAll'));afterAll(()=>trace('blocked-empty-afterAll'))})
 test('blocked case',()=>trace('blocked-case'),5000)
})
describe('following empty',()=>{beforeAll(()=>trace('following-empty-beforeAll',{wrapperPending}));afterAll(()=>trace('following-empty-afterAll',{wrapperPending}))})
